import{_ as l,l as i,o as e,c as s,v as r,p as d,x as t,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"DSL 与嵌入","description":"","frontmatter":{"title":"DSL 与嵌入","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dsl-embedding.md","filePath":"cs/dsl-embedding.md","lastUpdated":1789023840000}'),h={name:"cs/dsl-embedding.md"};function m(L,a,_,u,D,S){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="dsl-与嵌入" tabindex="-1">DSL 与嵌入 <a class="header-anchor" href="#dsl-与嵌入" aria-label="Permalink to &quot;DSL 与嵌入&quot;">​</a></h1><div class="epigraph"><p>领域语言可以是独立语法，也可以嵌入宿主：深嵌入建 AST 再编译，浅嵌入用宿主函数与重载当语法。</p><footer>—— 据 Hudak, Building Domain-Specific Embedded Languages；Fowler 对 DSL 的讨论；对照[宏](/cs/macros-hygiene) 与 MLIR 整理</footer></div><p>上一课<a href="/cs/mlir">MLIR</a> 给了编译基础设施。缺口是<strong>语言从哪来</strong>：SQL、正则、构建图。嵌入：Haskell 浅嵌入、Lisp 宏、Rust proc macro。本课钉深/浅，CompCert 下一课把「编译器该对」收束。不写业务 DSL 百科。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>独立 DSL：自己的 lex/yacc，要卫生、错误恢复、JIT 或解释。嵌入：复用宿主类型与工具。浅：组合子，难做跨函数优化。深：数据表示，可 lowering 到 MLIR/LLVM。缺口是<strong>这条选择</strong>，不是方言表。</p><p>宏：可当嵌入的语法糖，卫生课已讲捕获。</p><h3 id="浅嵌入不是「没有编译」" tabindex="-1">浅嵌入不是「没有编译」 <a class="header-anchor" href="#浅嵌入不是「没有编译」" aria-label="Permalink to &quot;浅嵌入不是「没有编译」&quot;">​</a></h3><p>仍有宿主编译。只是没有第二份优化器看见领域结构，除非重载技巧或多阶段（MetaOCaml）。</p><p><span class="marginnote">Hudak 1996。Fowler。Lua 作嵌入语言是另一方向（宿主嵌解释器）。本课编译器视角。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>浅：运算符重载建表达式模板（C++ Eigen 思想）。深：GADT 或 MLIR op。多阶段：生成宿主代码再编译。错误：深嵌入可发领域诊断；浅则是宿主类型错。</p>',11)),(e(),d(c,null,{default:t(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOM%5B%22%E9%A2%86%E5%9F%9F%E7%A8%8B%E5%BA%8F%22%5D%20--%3E%20SH%5B%22%E6%B5%85%EF%BC%9A%E5%AE%BF%E4%B8%BB%E5%87%BD%E6%95%B0%22%5D%0A%20%20DOM%20--%3E%20DP%5B%22%E6%B7%B1%EF%BC%9AAST%20%2F%20%E6%96%B9%E8%A8%80%22%5D%0A%20%20DP%20--%3E%20LOW%5B%22lowering%20%2F%20MLIR%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与<a href="/cs/peg-packrat">PEG</a>：独立 DSL 前端常用。与 Wasm：DSL 可目标 Wasm 沙箱。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>阶段混淆：浅嵌入在宿主运行时才算，可能把本该编译期的工作推迟——性能坑。不要用字符串拼接生成代码当卫生 DSL。</p><p>类型：嵌入要不要依值/线性，跟宿主走。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CompCert。后课默认：DSL 可独立或嵌入；深嵌入才好降到多层 IR。下一课 CompCert 与编译器正确性。</p><p>也不把 DSL 当网络协议 IDL 的全部。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>独立 DSL vs 浅/深嵌入，优化可见性不同。</li><li>深嵌入接到 MLIR/LLVM；浅复用宿主。</li><li>宏是嵌入的语法手段，要卫生。</li><li>出处：Hudak；Fowler；对照 Kohlbecker 宏、Lattner MLIR。</li></ul>',9))])}const B=l(h,[["render",m]]);export{f as __pageData,B as default};
